package dev.veyra.browser;
import android.widget.*;import org.json.*;
final class AccountProfile {
 static void show(MainActivity a){LinearLayout body=a.openSheet(a.t("Профиль и устройства","Profile and devices","Профіль і пристрої"));TextView status=a.label(a.t("Загрузка…","Loading…","Завантаження…"),14,a.muted);body.addView(status);new Thread(()->{try{JSONObject p=a.sync.request("profile",new JSONObject(),true),copies=a.sync.request("sync-list",new JSONObject(),true);a.runOnUiThread(()->{if(!body.isAttachedToWindow())return;body.removeView(status);body.addView(a.label(a.sync.email(),14,a.accent));EditText name=a.syncInput(body,a.t("Имя","Name","Ім’я"),false),device=a.syncInput(body,a.t("Название устройства","Device name","Назва пристрою"),false);name.setInputType(android.text.InputType.TYPE_CLASS_TEXT);device.setInputType(android.text.InputType.TYPE_CLASS_TEXT);name.setText(p.optString("display_name"));JSONArray sessions=p.optJSONArray("devices");String label=android.os.Build.MANUFACTURER+" "+android.os.Build.MODEL;if(sessions!=null)for(int i=0;i<sessions.length();i++){JSONObject s=sessions.optJSONObject(i);if(s!=null&&s.optBoolean("current")&&!s.optString("device_name").isEmpty())label=s.optString("device_name");}device.setText(label);a.action(body,a.t("Сохранить","Save","Зберегти"),"",()->a.syncWork(()->{a.sync.request("profile-save",new JSONObject().put("display_name",name.getText().toString()).put("device_name",device.getText().toString()).put("platform","android"),true);return a.t("Сохранено","Saved","Збережено");}));body.addView(a.label(a.t("Устройства","Devices","Пристрої"),18,a.text));if(sessions!=null)for(int i=0;i<sessions.length();i++){JSONObject s=sessions.optJSONObject(i);if(s==null)continue;String title=s.optString("device_name");if(title.isEmpty())title=s.optString("platform",a.t("Без названия","Unnamed","Без назви"));a.action(body,title,s.optBoolean("current")?a.t("Это устройство","This device","Цей пристрій"):s.optString("last_seen"),()->{if(s.optBoolean("current"))return;LinearLayout confirm=a.openSheet(a.t("Завершить сеанс?","End session?","Завершити сеанс?"));a.action(confirm,a.t("Завершить","End session","Завершити"),s.optString("device_name"),()->a.syncWork(()->{a.sync.request("session-revoke",new JSONObject().put("id",s.optString("id")),true);return a.t("Сеанс завершён","Session ended","Сеанс завершено");}));});}body.addView(a.label(a.t("Облачные копии","Cloud backups","Хмарні копії"),18,a.text));JSONArray rows=copies.optJSONArray("rows");if(rows!=null)for(int i=0;i<rows.length();i++){JSONObject row=rows.optJSONObject(i);if(row==null)continue;a.action(body,row.optString("platform"),row.optString("updated_at"),()->{LinearLayout confirm=a.openSheet(a.t("Удалить копию?","Delete backup?","Видалити копію?"));a.action(confirm,a.t("Удалить","Delete","Видалити"),a.t("Местные закладки сохранятся","Local bookmarks are kept","Місцеві закладки збережуться"),()->a.syncWork(()->{a.sync.request("sync-delete",new JSONObject().put("device_id",row.optString("device_id")),true);return a.t("Копия удалена","Backup removed","Копію видалено");}));});}});}catch(Exception error){a.runOnUiThread(()->status.setText(a.t("Не удалось загрузить профиль","Could not load profile","Не вдалося завантажити профіль")));}},"Veyra profile").start();}
}
